import React from "react";
import * as Menubar from "@radix-ui/react-menubar";
import { styled, focusRing } from "../../../stitches.config";
import { ArrowTopRightIcon } from "@radix-ui/react-icons";
import { ArrowDown } from "../../icons/ui/ArrowDown";
import { Box } from "../Box/Box";

export interface NavigationMenuProps {
  selected: string | React.ReactNode;
  options: { icon?: React.ReactNode; label: string; href: string }[];
}

const StyledMenubarRoot = styled(Menubar.Root, {
  display: "flex",
  backgroundColor: "$bg03",
  border: "2px solid $bg03",
  borderRadius: "$3",
  height: "fit-content",
});

const StyledMenubarTrigger = styled(Menubar.Trigger, {
  cursor: "pointer!important",
  all: "unset",
  ...focusRing,
  borderRadius: "$1",
  padding: "6px 16px",
  outline: "none",
  userSelect: "none",
  fontWeight: 600,
  lineHeight: "24px",
  color: "$body",
  fontSize: "$4",
  display: "flex",
  alignItems: "center",
  justifyContent: "space-between",
  gap: "$xs",
  backgroundColor: "$bg03",
  "&[data-highlighted], &[data-state='open']": {
    color: "white",
    backgroundColor: "$bg03",
  },
  [`&[data-state="open"] .DownIcon`]: {
    transform: "rotate(-180deg)",
    transition: "transform 250ms ease",
  },
});

const StyledMenubarContent = styled(Menubar.Content, {
  border: "2px solid $bg03",
  minWidth: "201px",
  backgroundColor: "$bg03",
  borderRadius: "$3",
  boxShadow:
    "0px 10px 38px -10px rgba(22, 23, 24, 0.35), 0px 10px 20px -15px rgba(22, 23, 24, 0.2)",
  animationDuration: "400ms",
  animationTimingFunction: "cubic-bezier(0.16, 1, 0.3, 1)",
  willChange: "transform, opacity",
  [`& div[role="menuitem"]:last-of-type`]: {
    borderBottom: "none",
  },
});

const StyledMenubarItem = styled(Menubar.Item, {
  cursor: "pointer!important",
  all: "unset",
  ...focusRing,
  padding: "8px 16px",
  fontSize: "$4",
  lineHeight: "24px",
  fontWeight: 600,
  color: "$body",
  display: "flex",
  alignItems: "center",
  height: "$lg",
  position: "relative",
  userSelect: "none",
  "&.inset": {
    paddingLeft: "$md",
  },
  "&[data-highlighted]": {
    color: "white",
  },
});

const StyledRightSlot = styled("div", {
  marginLeft: "auto",
  color: "$body",
  "[data-highlighted] > &": {
    color: "white",
  },
  ".DownIcon": {
    transform: "rotate(0deg)",
    transition: "transform 250ms ease",
  },
});

export const NavigationMenubarItemRightSlot = StyledRightSlot;
export const NavigationMenubarItem = StyledMenubarItem;
export const NavigationMenubarContent = StyledMenubarContent;
export const NavigationMenubarTrigger = StyledMenubarTrigger;
export const NavigationMenubarRoot = StyledMenubarRoot;

export const NavigationMenuComponent: React.FC<NavigationMenuProps> = ({
  selected,
  options,
}) => {
  const handleSelect = (href: string) => {
    window.open(href, "_blank");
  };

  return (
    <StyledMenubarRoot className="MenuBarComponent">
      <Menubar.Menu>
        <StyledMenubarTrigger>
          {selected}
          <StyledRightSlot>
            <Box
              as="span"
              className="DownIcon"
              css={{ display: "inline-flex" }}
            >
              <ArrowDown size="sm" />
            </Box>
          </StyledRightSlot>
        </StyledMenubarTrigger>
        <Menubar.Portal>
          <StyledMenubarContent align="end" sideOffset={5} alignOffset={-3}>
            {options.map((option, index) => (
              <StyledMenubarItem
                key={index}
                onSelect={() => handleSelect(option.href)}
              >
                {option.icon}
                {option.label}
                <StyledRightSlot>
                  <ArrowTopRightIcon />
                </StyledRightSlot>
              </StyledMenubarItem>
            ))}
          </StyledMenubarContent>
        </Menubar.Portal>
      </Menubar.Menu>
    </StyledMenubarRoot>
  );
};

export default NavigationMenuComponent;
